patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..f3b627a
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,67 @@
+/**
+ * Repro for "files on a different drive are not ignored on Windows".
+ * Simulates Windows on a non-Windows host: every `require("path")` /
+ * `require("node:path")` returns `path.win32`, and process.cwd() is "C:\\Project".
+ * Run: node repro/cross-drive-ignore.js
+ */
+"use strict";
+
+const Module = require("node:module");
+const realPath = require("node:path");
+
+if (process.platform !== "win32") {
+    const originalLoad = Module._load;
+
+    Module._load = function(request, ...rest) {
+        if (request === "path" || request === "node:path") {
+            return realPath.win32;
+        }
+        return originalLoad.call(this, request, ...rest);
+    };
+    process.cwd = () => "C:\\Project";
+}
+
+const path = require("node:path");
+const { Linter, ESLint } = require("../lib/api");
+
+const CWD = "C:\\Project";
+const files = {
+    "same drive, inside cwd (should be linted)": "C:\\Project\\foo.js",
+    "same drive, outside cwd (should be ignored)": "C:\\Other\\foo.js",
+    "different drive (should be ignored)": "F:\\foo.js"
+};
+
+console.log(`path.win32.relative(${JSON.stringify(CWD)}, "C:\\\\Other\\\\foo.js") =`, JSON.stringify(path.relative(CWD, "C:\\Other\\foo.js")));
+console.log(`path.win32.relative(${JSON.stringify(CWD)}, "F:\\\\foo.js")        =`, JSON.stringify(path.relative(CWD, "F:\\foo.js")));
+
+(async () => {
+    let bug = false;
+
+    console.log("\n--- Linter.verify (flat, cwd C:\\Project, no-undef: error) ---");
+    for (const [label, file] of Object.entries(files)) {
+        const linter = new Linter({ configType: "flat", cwd: CWD });
+        const msgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+        const linted = msgs.some(m => m.ruleId === "no-undef");
+
+        console.log(`${label}: ${file} -> ${linted ? "LINTED" : "not linted"}: ${msgs.map(m => m.message).join(" | ")}`);
+        if (label.startsWith("different drive") && linted) {
+            bug = true;
+        }
+    }
+
+    console.log("\n--- ESLint (overrideConfigFile: true = --no-config-lookup, cwd C:\\Project) ---");
+    const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: { rules: { "no-undef": "error" } } });
+
+    for (const [label, file] of Object.entries(files)) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+
+        console.log(`${label}: ${file} -> isPathIgnored=${ignored}; lintText: ${result.messages.map(m => m.message).join(" | ")}`);
+        if (label.startsWith("different drive") && !ignored) {
+            bug = true;
+        }
+    }
+
+    console.log(bug ? "\nBUG REPRODUCED: file on a different drive was linted / not ignored." : "\nNot reproduced.");
+    process.exitCode = bug ? 1 : 0;
+})();
